`include "prim_assert.sv"

/**
 * Tile-Link UL adapter for Register interface
 *
 * ICEBOX(#15822): Note that due to some modules with special needs (like
 * the vendored-in RV_DM), this module has been extended so that it
 * supports use cases outside of the generated reg_top module. This makes
 * this adapter and its parameterization options a bit heavy.
 *
 * We should in the future come back to this and refactor / align the
 * module and its parameterization needs.
 */

module tlul_adapter_reg
  import tlul_pkg::*;
  import prim_mubi_pkg::mubi4_t;
#(
  parameter  bit CmdIntgCheck      = 0,  // 1: Enable command integrity check
  parameter  bit EnableRspIntgGen  = 0,  // 1: Generate response integrity
  parameter  bit EnableDataIntgGen = 0,  // 1: Generate response data integrity
  parameter  int RegAw             = 8,  // Width of register address
  parameter  int RegDw             = 32, // Shall be matched with TL_DW
  parameter  int AccessLatency     = 0,  // 0: same cycle, 1: next cycle
  localparam int RegBw             = RegDw/8
) (
  input clk_i,
  input rst_ni,

  // TL-UL interface
  input  tl_h2d_t tl_i,
  output tl_d2h_t tl_o,

  // control interface
  input  mubi4_t  en_ifetch_i,
  output logic    intg_error_o,

  // Register interface
  output logic             re_o,
  output logic             we_o,
  output logic [RegAw-1:0] addr_o,
  output logic [RegDw-1:0] wdata_o,
  output logic [RegBw-1:0] be_o,
  input                    busy_i,
  // The following two signals are expected
  // to be returned in AccessLatency cycles.
  input        [RegDw-1:0] rdata_i,
  // This can be a write or read error.
  input                    error_i
);

  `ASSERT_INIT(AllowedLatency_A, AccessLatency inside {0, 1})

  localparam int IW  = $bits(tl_i.a_source);
  localparam int SZW = $bits(tl_i.a_size);

  logic outstanding_q;    // Indicates current request is pending
  logic a_ack, d_ack, hold_d_ack, hold_d_valid;

  logic [RegDw-1:0] rdata, rdata_q;
  logic             error_q, error, err_internal, instr_error, intg_error;

  logic addr_align_err;     // Size and alignment
  logic tl_err;             // Common TL-UL error checker

  logic [IW-1:0]  reqid_q;
  logic [SZW-1:0] reqsz_q;
  tl_d_op_e       rspop_q;

  logic rd_req, wr_req;

  assign a_ack   = tl_i.a_valid & tl_o.a_ready;
  assign d_ack   = tl_o.d_valid & tl_i.d_ready & ~hold_d_ack;
  // Request signal
  assign wr_req  = a_ack & ((tl_i.a_opcode == PutFullData) | (tl_i.a_opcode == PutPartialData));
  assign rd_req  = a_ack & (tl_i.a_opcode == Get);

  assign we_o    = wr_req & ~err_internal;
  assign re_o    = rd_req & ~err_internal;
  assign wdata_o = tl_i.a_data;
  assign be_o    = tl_i.a_mask;

  if (RegAw <= 2) begin : gen_only_one_reg
    assign addr_o  = '0;
  end else begin : gen_more_regs
    assign addr_o  = {tl_i.a_address[RegAw-1:2], 2'b00}; // generate always word-align
  end

always_ff @(posedge clk_i or negedge rst_ni) begin
  if (!rst_ni)    outstanding_q <= 1'b0;
  else if (a_ack) outstanding_q <= 1'b1;
  else if (d_ack) outstanding_q <= 1'b0;
end

always_ff @(posedge clk_i or negedge rst_ni) begin
  if (!rst_ni) begin
    reqid_q <= '0;
    reqsz_q <= '0;
    rspop_q <= AccessAck;
  end else if (a_ack) begin
    reqid_q <= tl_i.a_source;
    reqsz_q <= tl_i.a_size;
    // Return AccessAckData regardless of error
    rspop_q <= (rd_req) ? AccessAckData : AccessAck ;
  end
end

  if (AccessLatency == 1) begin : gen_access_latency1
    logic wr_req_q, rd_req_q;

`ifdef VERILATOR
    typedef enum logic [1:0] {
      TlulBug002Idle,
      TlulBug002HoldResp,
      TlulBug002HoldBaseline,
      TlulBug002InjectLateError
    } tlul_bug_002_state_e;

    int                   __tlul_bug_002_enabled;
    logic [2:0]           __tlul_bug_002_read_cnt_q;
    tlul_bug_002_state_e  __tlul_bug_002_state_q;
    logic                 __tlul_bug_002_late_error;

    initial begin
      __tlul_bug_002_enabled = 0;
      if ($test$plusargs("TLUL_BUG_002_INJECT")) begin
        __tlul_bug_002_enabled = 1;
      end
    end

always_ff @(posedge clk_i or negedge rst_ni) begin
  if (!rst_ni) begin
    __tlul_bug_002_read_cnt_q <= '0;
    __tlul_bug_002_state_q <= TlulBug002Idle;
  end else begin
    if (__tlul_bug_002_state_q != TlulBug002Idle) begin
      unique case (__tlul_bug_002_state_q)
        TlulBug002HoldResp: begin
          __tlul_bug_002_state_q <= TlulBug002HoldBaseline;
        end
        TlulBug002HoldBaseline: begin
          __tlul_bug_002_state_q <= TlulBug002InjectLateError;
        end
        TlulBug002InjectLateError: begin
          __tlul_bug_002_state_q <= TlulBug002Idle;
        end
        default: begin
          __tlul_bug_002_state_q <= TlulBug002Idle;
        end
      endcase
    end else if (__tlul_bug_002_enabled && a_ack && rd_req) begin
      if (__tlul_bug_002_read_cnt_q < 3'h7) begin
        __tlul_bug_002_read_cnt_q <= __tlul_bug_002_read_cnt_q + 3'h1;
      end
      // Sink the existing directed witness window into the injection:
      // the target read is held in a synthetic backpressure window long
      // enough for rd_req_q to fall low before a one-cycle late error
      // pulse mutates the buffered response.
      if (__tlul_bug_002_read_cnt_q == 3'h2) begin
        __tlul_bug_002_state_q <= TlulBug002HoldResp;
      end
    end
  end
end

    assign hold_d_ack = (__tlul_bug_002_state_q == TlulBug002HoldResp) ||
                        (__tlul_bug_002_state_q == TlulBug002HoldBaseline);
    assign hold_d_valid = (__tlul_bug_002_state_q == TlulBug002HoldResp) ||
                          (__tlul_bug_002_state_q == TlulBug002HoldBaseline);
    assign __tlul_bug_002_late_error =
        (__tlul_bug_002_state_q == TlulBug002InjectLateError);
`else
    assign hold_d_ack = 1'b0;
    assign hold_d_valid = 1'b0;
`endif

always_ff @(posedge clk_i or negedge rst_ni) begin
  if (!rst_ni) begin
    rdata_q  <= '0;
    error_q  <= 1'b0;
    wr_req_q <= 1'b0;
    rd_req_q <= 1'b0;
  end else begin
    rd_req_q <= rd_req;
    wr_req_q <= wr_req;
    // Addressing phase
    if (a_ack) begin
      error_q <= err_internal;
    // Response phase
    end else begin
      error_q <= error;
      rdata_q <= rdata;
    end
  end
end

always_ff @(posedge clk_i or negedge rst_ni) begin
  if (!rst_ni) begin
    rdata_q <= '0;
    error_q <= 1'b0;
  end else if (a_ack) begin
    rdata_q <= (error_i || err_internal || wr_req) ? '1 : rdata_i;
    error_q <= error_i || err_internal;
  end
end

  assign rdata = rdata_q;
  assign error = error_q;
end

tlul_pkg::tl_d2h_t tl_o_pre;
assign tl_o_pre = '{
  a_ready:  ~(outstanding_q | busy_i),
  d_valid:  outstanding_q & ~hold_d_valid,
  d_opcode: rspop_q,
  d_param:  '0,
  d_size:   reqsz_q,
  d_source: reqid_q,
  d_sink:   '0,
  d_data:   rdata,
  d_user:   '0,
  d_error:  error
};

// outgoing integrity generation
tlul_rsp_intg_gen #(
  .EnableRspIntgGen(EnableRspIntgGen),
  .EnableDataIntgGen(EnableDataIntgGen),
  .UserInIsZero(1'b1)
) u_rsp_intg_gen (
  .tl_i(tl_o_pre),
  .tl_o(tl_o)
);

if (CmdIntgCheck) begin : gen_cmd_intg_check
  logic intg_error_q;
  tlul_cmd_intg_chk u_cmd_intg_chk (
    .tl_i(tl_i),
    .err_o(intg_error)
  );

  assign intg_error_o = intg_error_q;
end else begin : gen_no_cmd_intg_check
  assign intg_error = 1'b0;
  assign intg_error_o = 1'b0;
end

////////////////////
// Error Handling //
////////////////////

// An instruction type transaction is only valid if en_ifetch is enabled
assign instr_error = prim_mubi_pkg::mubi4_test_true_strict(tl_i.a_user.instr_type) &
                     prim_mubi_pkg::mubi4_test_false_loose(en_ifetch_i);

assign err_internal = addr_align_err | tl_err | instr_error | intg_error;

always_comb begin
  if (wr_req) begin
    // Only word-align is accepted based on comportability spec
    addr_align_err = |tl_i.a_address[1:0];
  end else begin
    // No request
    addr_align_err = 1'b0;
  end
end

module tlul_fifo_sync #(
  parameter bit          ReqPass = 1'b1,
  parameter bit          RspPass = 1'b1,
  parameter int unsigned ReqDepth = 2,
  parameter int unsigned RspDepth = 2,
  parameter int unsigned SpareReqW = 1,
  parameter int unsigned SpareRspW = 1
) (
  input                     clk_i,
  input                     rst_ni,
  input  tlul_pkg::tl_h2d_t tl_h_i,
  output tlul_pkg::tl_d2h_t tl_h_o,
  output tlul_pkg::tl_h2d_t tl_d_o,
  input  tlul_pkg::tl_d2h_t tl_d_i,
  input  [SpareReqW-1:0]    spare_req_i,
  output [SpareReqW-1:0]    spare_req_o,
  input  [SpareRspW-1:0]    spare_rsp_i,
  output [SpareRspW-1:0]    spare_rsp_o
);

  // Put everything on the request side into one FIFO
  localparam int unsigned REQFIFO_WIDTH = $bits(tlul_pkg::tl_h2d_t) -2 + SpareReqW;

`ifdef VERILATOR
  logic [REQFIFO_WIDTH-1:0] reqfifo_rdata;
  logic [REQFIFO_WIDTH-1:0] reqfifo_wdata;

  // Unified hybrid witness for tlul_bug_001. When enabled with
  // +TLUL_BUG_001_INJECT, a magic UART CTRL write is accepted into the merged
  // request FIFO with a corrupted request word: the write data is modified and
  // the corresponding data integrity bits are updated to stay self-consistent.
  // This keeps the fault model on the merged request word itself while also
  // allowing firmware to observe the downstream UART CSR consequence.
  bit tlul_bug_001_inject_en = 1'b0;
  localparam logic [31:0] TlulBug001MagicData  = 32'hdead_beef;
  localparam logic [31:0] TlulBug001TargetAddr = 32'h4000_0010;
  localparam logic [31:0] TlulBug001FlipMask   = 32'h0000_0010;

  wire tlul_bug_001_fire;
  wire [31:0] tlul_bug_001_corrupted_data;
  wire [tlul_pkg::DataIntgWidth-1:0] tlul_bug_001_corrupted_data_intg;

  initial begin
    if ($test$plusargs("TLUL_BUG_001_INJECT")) begin
      tlul_bug_001_inject_en = 1'b1;
    end
  end

  assign tlul_bug_001_fire =
      tlul_bug_001_inject_en &&
      tl_h_i.a_valid &&
      tl_h_o.a_ready &&
      (tl_h_i.a_opcode == tlul_pkg::PutFullData) &&
      (tl_h_i.a_data == TlulBug001MagicData) &&
      (tl_h_i.a_address == TlulBug001TargetAddr);

  assign tlul_bug_001_corrupted_data =
      tl_h_i.a_data ^ TlulBug001FlipMask;
  assign tlul_bug_001_corrupted_data_intg =
      tlul_pkg::get_data_intg(tlul_bug_001_corrupted_data);
  assign reqfifo_wdata =
      tlul_bug_001_fire
          ? {tl_h_i.a_opcode,
             tl_h_i.a_param,
             tl_h_i.a_size,
             tl_h_i.a_source,
             tl_h_i.a_address,
             tl_h_i.a_mask,
             tlul_bug_001_corrupted_data,
             tl_h_i.a_user.rsvd,
             tl_h_i.a_user.instr_type,
             tl_h_i.a_user.cmd_intg,
             tlul_bug_001_corrupted_data_intg,
             spare_req_i}
          : {tl_h_i.a_opcode,
             tl_h_i.a_param,
             tl_h_i.a_size,
             tl_h_i.a_source,
             tl_h_i.a_address,
             tl_h_i.a_mask,
             tl_h_i.a_data,
             tl_h_i.a_user,
             spare_req_i};
